const MODEL_SONNET = "claude-sonnet-4-20250514";
const MODEL_HAIKU = "claude-haiku-4-5-20251001";

const DOCX_MEDIA = "application/vnd.openxmlformats-officedocument.wordprocessingml.document";

function documentMediaTypeForAttachment(a) {
  if (a.type && a.type !== "application/octet-stream" && !a.type.startsWith("image/")) return a.type;
  const n = (a.name || "").toLowerCase();
  if (n.endsWith(".docx")) return DOCX_MEDIA;
  if (n.endsWith(".doc")) return "application/msword";
  if (n.endsWith(".pdf")) return "application/pdf";
  return "application/pdf";
}

// options opzionali: model, max_tokens, fullDocumentGeneration
async function callAI(userMsg, mainDoc = null, attachments = [], sysOverride = null, options = {}) {
  const blocks = [];
  if (mainDoc) {
    blocks.push({ type: "document", source: { type: "base64", media_type: "application/pdf", data: mainDoc } });
  }
  for (const a of attachments) {
    const isImg = a.type.startsWith("image/");
    if (isImg) {
      blocks.push({ type: "image", source: { type: "base64", media_type: a.type, data: a.data } });
    } else {
      const media_type = documentMediaTypeForAttachment(a);
      blocks.push({ type: "document", source: { type: "base64", media_type, data: a.data } });
    }
  }
  blocks.push({ type: "text", text: userMsg });
  const content = blocks.length === 1 ? userMsg : blocks;
  const maxTokens = options.max_tokens ?? (options.fullDocumentGeneration ? GENERATION_MAX_TOKENS : DEFAULT_MAX_TOKENS);
  const text = await anthropicMessages({
    model: options.model || MODEL_SONNET,
    max_tokens: maxTokens,
    system: sysOverride || SYS_PROMPT,
    messages: [{ role: "user", content }],
  });
  try {
    return JSON.parse(text);
  } catch {
    throw new Error(
      "La risposta dell'AI non è JSON valido. Riformula la richiesta o riprova; per documenti molto lunghi conviene chiedere modifiche più mirate.",
    );
  }
}

function preserveBlobsAfterPatch(patched, prev) {
  return {
    ...patched,
    logoEvento: prev.logoEvento ?? patched.logoEvento ?? null,
    allegato2Files: prev.allegato2Files || [],
    s3: { ...(patched.s3 || {}), evacuazionePiano: prev.s3?.evacuazionePiano ?? patched.s3?.evacuazionePiano ?? null },
  };
}

/** Path che non devono essere toccati da JSON Patch (allineato al prompt SYS_PATCH_EDITOR). */
const PROTECTED_PATCH_PREFIXES = ["/logoEvento", "/allegato2Files", "/s3/evacuazionePiano"];

function assertPatchDoesNotTouchProtectedAssets(patchOps) {
  for (const op of patchOps) {
    const paths = [op.path, op.from].filter((x) => typeof x === "string");
    for (const p of paths) {
      if (!p.startsWith("/")) {
        throw new Error('Ogni operazione patch deve usare un path assoluto che inizi con "/".');
      }
      for (const prefix of PROTECTED_PATCH_PREFIXES) {
        if (p === prefix || p.startsWith(`${prefix}/`)) {
          throw new Error(
            "La patch tenta di modificare logo, Allegato 2 o piano evacuazione: questi elementi si gestiscono solo dall'interfaccia. Riformula la richiesta in testo.",
          );
        }
      }
    }
  }
}

/** Applica JSON Patch in locale; preserva blob allegati/logo. */
function applyJsonPatchToDocument(base, patchOps) {
  if (!Array.isArray(patchOps) || patchOps.length === 0) {
    throw new Error("La risposta non contiene operazioni di patch valide.");
  }
  assertPatchDoesNotTouchProtectedAssets(patchOps);
  const clone = structuredClone(base);
  try {
    applyPatch(clone, patchOps, true, true);
  } catch (pe) {
    throw new Error(`Impossibile applicare la patch al documento: ${pe?.message || "operazione non valida"}.`);
  }
  return preserveBlobsAfterPatch(clone, base);
}

